create policy "output_history_admin_write" on "public"."output_history" as PERMISSIVE for ALL to "authenticated" using (current_user_is_app_admin()) with check (current_user_is_app_admin());

grant select, insert, update, delete on public."output_history" to "authenticated";

create policy "output_history_read_scope" on "public"."output_history" as PERMISSIVE for SELECT to "authenticated" using ((current_user_is_app_admin() OR ((current_user_app_role() <> 'worker'::text) AND (project_id IN ( SELECT current_user_project_ids() AS current_user_project_ids))) OR ((current_user_app_role() = 'worker'::text) AND (owner_employee_id = current_user_employee_id()))));

grant SELECT on public."output_history" to "authenticated";

create policy "output_history_write_scope" on "public"."output_history" as PERMISSIVE for ALL to "authenticated" using ((current_user_is_app_admin() OR ((current_user_app_role() <> 'worker'::text) AND (project_id IN ( SELECT current_user_project_ids() AS current_user_project_ids))))) with check ((current_user_is_app_admin() OR ((current_user_app_role() <> 'worker'::text) AND (project_id IN ( SELECT current_user_project_ids() AS current_user_project_ids)))));

grant select, insert, update, delete on public."output_history" to "authenticated";

create policy "worker_output_history_delete" on "public"."output_history" as PERMISSIVE for DELETE to "authenticated" using (((current_user_app_role() = 'worker'::text) AND current_user_can_edit_task_output(task_id, project_id)));

grant DELETE on public."output_history" to "authenticated";

create policy "worker_output_history_insert" on "public"."output_history" as PERMISSIVE for INSERT to "authenticated" with check (((current_user_app_role() = 'worker'::text) AND (owner_employee_id = current_user_employee_id()) AND current_user_can_edit_task_output(task_id, project_id)));

grant INSERT on public."output_history" to "authenticated";

create policy "worker_output_history_update" on "public"."output_history" as PERMISSIVE for UPDATE to "authenticated" using (((current_user_app_role() = 'worker'::text) AND current_user_can_edit_task_output(task_id, project_id))) with check (((current_user_app_role() = 'worker'::text) AND current_user_can_edit_task_output(task_id, project_id)));

grant UPDATE on public."output_history" to "authenticated";

create policy "employee_review_images_admin_delete" on "storage"."objects" as PERMISSIVE for DELETE to "authenticated" using (((bucket_id = 'employee-review-images'::text) AND current_user_is_app_admin()));

create policy "employee_review_images_admin_insert" on "storage"."objects" as PERMISSIVE for INSERT to "authenticated" with check (((bucket_id = 'employee-review-images'::text) AND current_user_is_app_admin()));

create policy "employee_review_images_admin_read" on "storage"."objects" as PERMISSIVE for SELECT to "authenticated" using (((bucket_id = 'employee-review-images'::text) AND current_user_is_app_admin()));

create policy "work_resource_images_read_scope" on "storage"."objects" as PERMISSIVE for SELECT to "authenticated" using (((bucket_id = 'work-resource-images'::text) AND (current_user_is_app_admin() OR ((storage.foldername(name))[1] IN ( SELECT current_user_explicit_project_ids() AS current_user_explicit_project_ids)))));

create policy "work_resource_images_write_scope" on "storage"."objects" as PERMISSIVE for ALL to "authenticated" using (((bucket_id = 'work-resource-images'::text) AND (current_user_is_app_admin() OR ((current_user_app_role() = ANY (ARRAY['operator_all'::text, 'operator_no_profit'::text, 'operator_output_admin'::text])) AND ((storage.foldername(name))[1] IN ( SELECT current_user_explicit_project_ids() AS current_user_explicit_project_ids)))))) with check (((bucket_id = 'work-resource-images'::text) AND (current_user_is_app_admin() OR ((current_user_app_role() = ANY (ARRAY['operator_all'::text, 'operator_no_profit'::text, 'operator_output_admin'::text])) AND ((storage.foldername(name))[1] IN ( SELECT current_user_explicit_project_ids() AS current_user_explicit_project_ids))))));

create policy "project_select_self_or_admin" on "public"."app_user_projects" as PERMISSIVE for SELECT to "authenticated" using (((user_id = auth.uid()) OR current_user_is_app_admin()));

grant SELECT on public."app_user_projects" to "authenticated";

