-- Restrict only the app routines, not unrelated extension functions.
do $acl$
declare f record;
begin
 for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='public' and p.proname = any(array['current_user_app_role', 'current_user_employee_id', 'current_user_is_app_admin', 'current_user_project_ids', 'current_user_explicit_project_ids', 'current_user_can_access_task', 'current_user_can_edit_task_output', 'app_save_setting', 'app_admin_upsert_auth_account', 'validate_employee_review_entry', 'guard_public_daily_setting', 'get_public_daily_status'])
 loop
  execute format('revoke all on function %s from public, anon, authenticated', f.signature);
  execute format('grant execute on function %s to authenticated, service_role', f.signature);
 end loop;
end;
$acl$;
grant execute on function public.get_public_daily_status() to anon;
